CREATE TABLE IF NOT EXISTS public."tEventOffer" (
    "offerId"                   INT GENERATED BY DEFAULT AS IDENTITY,
    "offerNumber"               INT NOT NULL,
    "eventId"                   INT NOT NULL DEFAULT 1,
    "page"                      INT NOT NULL DEFAULT 1,
    "pagePosition"              INT NOT NULL DEFAULT 1,
    "status"                    VARCHAR(50) DEFAULT 'Draft',
    "offerTypeId"               INT NOT NULL,
    "offerType"                 VARCHAR(100) NOT NULL,
    "commercialOfferType"       VARCHAR(100),
    "commercialOfferItemClass1" VARCHAR(100),
    "commercialCategoryManager" VARCHAR(100),
    "offerName"                 VARCHAR(255),
    "offerDescription"          VARCHAR(500),
    "brand"                     VARCHAR(100) NOT NULL,
    "country"                   VARCHAR(10) NOT NULL DEFAULT 'AU',
    "categoryCostType"          VARCHAR(50) DEFAULT 'NAT AVG COST',
    "isRewards"                 BOOLEAN DEFAULT FALSE,
    "spend1"                    NUMERIC(19, 5) NOT NULL,
    "savePct1"                  NUMERIC(19, 5) NOT NULL,
    "spend2"                    NUMERIC(19, 5),
    "savePct2"                  NUMERIC(19, 5),
    "spend3"                    NUMERIC(19, 5),
    "savePct3"                  NUMERIC(19, 5),
    "thresholdAmount"           NUMERIC(19, 5),
    "discountPercent"           NUMERIC(19, 5),
    "discountAmount"            NUMERIC(19, 5),
    "incrementalPercentage"     NUMERIC(19, 5) DEFAULT 0,
    "spacePurchase"             NUMERIC(19, 5) DEFAULT 0,
    "forecastUnits"             INT DEFAULT 0,
    "everydayUnits"             NUMERIC(19, 5) DEFAULT 0,
    "incrementalUnits"          INT DEFAULT 0,
    "forecastCost"              NUMERIC(19, 5) DEFAULT 0,
    "forecastSales"             NUMERIC(19, 5) DEFAULT 0,
    "forecastTradeMargin"       NUMERIC(19, 5) DEFAULT 0,
    "forecastTradeMargin$"      NUMERIC(19, 5) DEFAULT 0,
    "forecastTmPercent"         NUMERIC(19, 5) DEFAULT 0,
    "forecastTradeMargin%"      NUMERIC(19, 5) DEFAULT 0,
    "incrementalSales"          NUMERIC(19, 5) DEFAULT 0,
    "incrementalSales$"         NUMERIC(19, 5) DEFAULT 0,
    "incrementalTm"             NUMERIC(19, 5) DEFAULT 0,
    "incrementalTm$"            NUMERIC(19, 5) DEFAULT 0,
    "totalSupplierIncome"       NUMERIC(19, 5) DEFAULT 0,
    "totalScanSupport$"         NUMERIC(19, 5) DEFAULT 0,
    "totalScanSupport%"         NUMERIC(19, 5) DEFAULT 0,
    "everydayPrice"             NUMERIC(19, 5),
    "everydayPriceGst"          NUMERIC(19, 5),
    "advertisedPrice"           NUMERIC(19, 5),
    "advertisedPriceGst"        NUMERIC(19, 5),
    "saveValue"                 NUMERIC(19, 5),
    "savePercent"               NUMERIC(19, 5),
    "calculatedSavePercent"     NUMERIC(19, 5),
    "calculatedSaveValue"       NUMERIC(19, 5),
    "isClearance"               BOOLEAN DEFAULT FALSE,
    "isExclusive"               BOOLEAN DEFAULT FALSE,
    "isNew"                     BOOLEAN DEFAULT FALSE,
    "isLowestPrice"             BOOLEAN DEFAULT FALSE,
    "isLimitQuantity"           INT DEFAULT 0,
    "isOnlineOnly"              BOOLEAN DEFAULT FALSE,
    "isNotAvailableOnline"      BOOLEAN DEFAULT FALSE,
    "isRaincheck"               BOOLEAN DEFAULT FALSE,
    "isOrderYoursToday"         BOOLEAN DEFAULT FALSE,
    "IsNotAvailableAllStores"   BOOLEAN DEFAULT FALSE,
    "IsLimitedStoreStock"       BOOLEAN DEFAULT FALSE,
    "isWhileStockLast"          BOOLEAN DEFAULT FALSE,
    "IsStoreStockOnly"          BOOLEAN DEFAULT FALSE,
    "imageReference"            VARCHAR(255),
    "copyReference"             VARCHAR(255),
    "OtherDetails"              TEXT,
    "Comments"                  TEXT,
    "createdAt"                 TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    "createdBy"                 VARCHAR(100),
    "updatedAt"                 TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    "updatedBy"                 VARCHAR(100),
    "isOfferEdited"             BOOLEAN DEFAULT FALSE,
    "isOfferActive"             BOOLEAN DEFAULT TRUE,

    CONSTRAINT pk_teventoffer PRIMARY KEY ("offerId", "offerNumber")
);

CREATE INDEX IF NOT EXISTS idx_teventoffer_page_pos ON public."tEventOffer" ("page", "pagePosition");
CREATE INDEX IF NOT EXISTS idx_teventoffer_brand_country ON public."tEventOffer" ("brand", "country");